@Service
@RequiredArgsConstructor
public class Xgg74CommandService {

    private final Xgg74Repository saleRepository;
    private final Xzj27QueryService orderBidQueryService;
    private final Xkh73CommandService notificationCommandService;
    private final Xrd81QueryService userQueryService;
    private final Xxn30CommandService sellerShipmentCommandService;
    private final Xbr34QueryService bankAccountQueryService;
    private final Xgz75CommandService saleBankAccountCommandService;


    @Transactional
    public Xgg74 createInstantSale(
            Long orderBidId,
            String sellerEmail,
            String returnAddress,
            String postalCode,
            String receiverPhone
    ) {

        Xzj27 orderBid = orderBidQueryService.findById(orderBidId)
                .orElseThrow(() -> new IllegalArgumentException("해당 OrderBid를 찾을 수 없습니다."));


        Xrd81 seller = userQueryService.findByEmail(sellerEmail);


        Xdh20 productSize = orderBid.getProductSize();


        Xgg74 sale = Xgg74.builder()
                .seller(seller)
                .productSize(productSize)
                .returnAddress(returnAddress)
                .postalCode(postalCode)
                .receiverPhone(receiverPhone)
                .status(Xgg74Status.PENDING_SHIPMENT)
                .build();

        Xgg74 savedSale = saleRepository.save(sale);



        Xbr34InfoDto bankAccountInfo = bankAccountQueryService.getBankAccount(seller.getEmail());
        Xgz75 saleBankAccount = saleBankAccountCommandService.createSaleBankAccount(
                bankAccountInfo.getBankName(),
                bankAccountInfo.getAccountNumber(),
                bankAccountInfo.getAccountHolder(),
                savedSale
        );
        savedSale.assignSaleBankAccount(saleBankAccount);


        orderBid.assignSale(savedSale);
        orderBid.updateStatus(Xtz73Status.MATCHED);


        Xrd81 buyer = orderBid.getUser();
        notificationCommandService.createNotification(
                buyer.getId(),
                Xzv64.SHOPPING,
                Xkh73Type.BID,
                "구매 입찰에 판매자가 등록되었습니다. 확인해보세요!"
        );

        return savedSale;
    }

    @Transactional
    public Xgg74 createSale(Xrd81 seller, Xdh20 productSize, String returnAddress,
                           String postalCode, String receiverPhone, boolean isWarehouseStorage) {

        Xbr34InfoDto bankAccountInfo = bankAccountQueryService.getBankAccount(seller.getEmail());


        Xgg74 sale = Xgg74.builder()
                .seller(seller)
                .productSize(productSize)
                .returnAddress(returnAddress)
                .postalCode(postalCode)
                .receiverPhone(receiverPhone)
                .isWarehouseStorage(isWarehouseStorage)
                .status(Xgg74Status.PENDING_SHIPMENT)
                .build();

        Xgg74 savedSale = saleRepository.save(sale);


        Xgz75 saleBankAccount = saleBankAccountCommandService.createSaleBankAccount(
                bankAccountInfo.getBankName(),
                bankAccountInfo.getAccountNumber(),
                bankAccountInfo.getAccountHolder(),
                savedSale
        );


        savedSale.assignSaleBankAccount(saleBankAccount);


        notificationCommandService.createNotification(
                seller.getId(),
                Xzv64.SHOPPING,
                Xkh73Type.BID,
                "판매 입찰이 등록되었습니다."
        );

        return savedSale;
    }


    @Transactional
    public Xxn30 createSellerShipment(Long saleId, String courier, String trackingNumber) {

        Xxn30 shipment = sellerShipmentCommandService.createSellerShipment(saleId, courier, trackingNumber);


        updateSaleStatus(saleId, Xgg74Status.IN_TRANSIT);

        return shipment;
    }

    @Transactional
    public void updateSaleStatus(Long saleId, Xgg74Status newStatus) {
        Xgg74 sale = saleRepository.findById(saleId)
                .orElseThrow(() -> new IllegalArgumentException("해당 Sale을 찾을 수 없습니다: " + saleId));


        System.out.println("현재 상태: " + sale.getStatus());
        System.out.println("전환하려는 상태: " + newStatus);
        if (!sale.getStatus().canTransitionTo(newStatus)) {
            throw new IllegalStateException("Xgg74 상태를 " + newStatus + "로 전환할 수 없습니다.");
        }

        sale.updateStatus(newStatus);
    }

    @Transactional
    public void deleteSale(Long saleId) {

        Xgg74 sale = saleRepository.findById(saleId)
                .orElseThrow(() -> new IllegalArgumentException("해당 Sale을 찾을 수 없습니다: " + saleId));


        saleRepository.delete(sale);
    }


}


